class Solution {
public:
    vector<int> elementInNums(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> answer;
        for (const auto& q : queries) {
            int time = q[0] % (2 * n);
            int length = time < n ? n - time : time - n;
            int offset = time < n ? time : 0;
            answer.push_back(q[1] < length ? nums[offset + q[1]] : -1);
        }
        return answer;
    }
};
